<style>.portfolio-settings-head{display:flex;justify-content:space-between;align-items:center;margin-bottom:1.25rem}.portfolio-settings-card{padding:1.4rem;margin-bottom:1rem}.portfolio-settings-card h5{font-weight:700;color:#334257;margin-bottom:.5rem}.portfolio-settings-card hr{margin:1.8rem 0}.color-input{height:42px;padding:.25rem}.portfolio-cover-upload{display:flex;align-items:center;gap:1rem;min-height:96px;padding:.85rem;border:1px dashed #9eb5cc;border-radius:.6rem;background:linear-gradient(135deg,#fbfdff,#f3f7fb)}.portfolio-cover-upload img,.portfolio-cover-upload>i{width:124px;height:76px;border-radius:.4rem;object-fit:cover}.portfolio-cover-upload>i{display:grid;place-items:center;background:#e4edf6;color:#6684a2;font-size:1.55rem}.portfolio-cover-button{display:inline-flex;align-items:center;gap:.45rem;padding:.55rem .85rem;border:0;border-radius:.35rem;background:#1455ac;color:#fff!important;font-size:.82rem;font-weight:700;cursor:pointer;box-shadow:0 3px 8px rgba(20,85,172,.2);transition:.18s}.portfolio-cover-button:hover{background:#0e478f;transform:translateY(-1px)}.portfolio-crop-body{min-height:390px;max-height:65vh;background:#18202b}.portfolio-crop-body img{display:block;max-width:100%}.portfolio-steps{padding-left:1.15rem;color:#6c757d}.portfolio-steps li{margin-bottom:.75rem}.theme-picker{display:grid;grid-template-columns:minmax(220px,330px);gap:1rem}.theme-choice{display:block;margin:0;cursor:pointer}.theme-choice input{position:absolute;opacity:0}.theme-preview{position:relative;display:block;height:145px;padding:13px;overflow:hidden;border:2px solid transparent;border-radius:.55rem;background:#f5f6f8;transition:.18s}.theme-choice input:checked+.theme-preview{border-color:#1455ac;box-shadow:0 0 0 3px rgba(20,85,172,.13)}.theme-choice strong{display:block;margin:.65rem 0 .12rem;color:#334257;font-size:.9rem}.theme-choice small{color:#6c757d;font-size:.76rem}.theme-preview i{display:block;width:30%;height:5px;margin-bottom:10px;background:#26374b}.theme-preview b{display:block;width:76%;height:16px;margin-bottom:13px;background:#fff}.theme-preview em{display:inline-block;height:72px;background:linear-gradient(135deg,#335c7b,#ba8b55)}.theme-preview em:nth-of-type(1){width:62%;margin-right:2%}.theme-preview em:nth-of-type(2){width:36%}.theme-preview em:nth-of-type(3){display:none}.theme-preview--bold{background:#172230}.theme-preview--bold i{background:#fff}@media(max-width:767.98px){.theme-picker{grid-template-columns:1fr}.theme-preview{height:125px}.portfolio-crop-body{min-height:260px}}@media(max-width:575.98px){.portfolio-settings-head{align-items:flex-start;flex-direction:column}}</style>
