@section('js')
<script src="https://cdnjs.cloudflare.com/ajax/libs/cropperjs/1.6.2/cropper.min.js"></script>
<script>$(function(){let cropper,selectedFile,cropApplied=false;const input=document.getElementById('portfolio_cover'),image=document.getElementById('portfolioCropImage'),preview=document.getElementById('portfolioCoverPreview');input.addEventListener('change',function(){selectedFile=this.files[0];if(!selectedFile)return;cropApplied=false;image.src=URL.createObjectURL(selectedFile);$('#coverCropModal').modal('show');});$('#coverCropModal').on('shown.bs.modal',function(){if(cropper)cropper.destroy();cropper=new Cropper(image,{aspectRatio:16/9,viewMode:1,autoCropArea:1,responsive:true});}).on('hidden.bs.modal',function(){if(cropper){cropper.destroy();cropper=null;}if(!cropApplied)input.value='';});document.getElementById('applyPortfolioCrop').addEventListener('click',function(){if(!cropper||!selectedFile)return;cropper.getCroppedCanvas({width:1600,height:900,imageSmoothingQuality:'high'}).toBlob(function(blob){const croppedFile=new File([blob],'portfolio-cover.jpg',{type:'image/jpeg'}),transfer=new DataTransfer();transfer.items.add(croppedFile);input.files=transfer.files;preview.src=URL.createObjectURL(blob);preview.style.display='block';const icon=document.getElementById('portfolioCoverIcon');if(icon)icon.style.display='none';cropApplied=true;$('#coverCropModal').modal('hide');},'image/jpeg',.9);});});</script>
@stop
